test("sheet notes scenario 3", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-10");
  expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "floor", "0.50");
  await ui.setSetting(pg_uma, "terms-B", "20");
  await ui.setSetting(pg_uma, "grace-days", "3");
  await ui.setSetting(pg_uma, "entry-date", "2026-03-05");
  expect(await ui.addHoliday(pg_uma, "2026-03-16")).toBe(true);
  await ui.setSetting(pg_uma, "grace-B", "5");
  await ui.setSetting(pg_uma, "proof-threshold-A", "4.00");
  await ui.setSetting(pg_uma, "pot", "7.77");
  await ui.setSetting(pg_uma, "alert-threshold", "3.00");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "33.33"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "12.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "33.33"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "12.50", "from": "2026-03-10", "to": "2026-03-12"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P2", "from": "2026-03-16", "to": "2026-03-31"})).toBe(true);
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "C", "terms": "20"}));
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A", "contact": " Ada@x "}));
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B", "terms": "3"}));
  expect(await ui.addCrew(pg_uma, "C1", "Cam")).toBe(true);
  expect(await ui.addCrewMember(pg_uma, "C1", "Ada")).toBe(true);
  expect(await ui.addCrewMember(pg_uma, "C1", "Ben")).toBe(true);
  await ui.setToday(pg_uma, "2026-03-21");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00", "from": "2026-04-05"})).toBe(true);
  expect(await ui.addClaim(pg_uma, p_ben, {"amount": "4.00", "date": "2026-03-09", "ref": "R-2"})).toBeNull();
test("sheet notes scenario 2", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-04-05");
  await ui.setSetting(pg_uma, "clerk-limit", "3.00");
  await ui.setSetting(pg_uma, "floor", "0.50");
  await ui.setSetting(pg_uma, "cap", "5.00");
  await ui.setSetting(pg_uma, "entry-date", "2026-03-01");
  await ui.loadSheet(pg_uma, `${sheet}-p`);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "12.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "10.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "20.00"})).toBe(true);
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "C"}));
  await ui.loadSheet(pg_uma, sheet);
  await ui.setSetting(pg_uma, "parent", `${sheet}-p`);
  await ui.setSetting(pg_uma, "pot", "100.00");
  await ui.setSetting(pg_uma, "fiscal-start-month", "7");
  await ui.setSetting(pg_uma, "alert-threshold", "1.00");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "33.33"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P2", "from": "2026-03-16", "to": "2026-03-31"})).toBe(true);
  expect(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B", "contact": " Ada@x "})).toBeNull();
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "B"}));
  expect(await ui.editPerson(pg_uma, p_cam, {"terms": "20", "termsFrom": "2026-03-12"})).toBe(true);
  const pl_cam_1 = ui.must(await ui.addPlan(pg_uma, p_cam, {"amount": "99.95", "start": "2026-02-20", "end": "2026-04-30", "day": "31"}));
  await ui.setSetting(pg_uma, "entry-date", "");
  expect(await ui.generatePlans(pg_uma)).toBe(2);
  const c_cam_0 = await ui.claimAt(pg_uma, p_cam, 0);
  const c_cam_1 = await ui.claimAt(pg_uma, p_cam, 1);
  expect(await ui.hold(pg_uma, p_cam, {"from": "2026-03-01"})).toBe(true);
  expect(await ui.periodAction(pg_uma, "P1", "close")).toBe(true);
  expect(await ui.importRates(pg_uma, "B,7.50\nB,5.00,2026-03-05")).toBe(2);
  expect(await ui.statement(pg_uma, p_cam)).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "7.50"})).toBe(true);
  await ui.refresh(pg_uma);
  await expect(pg_uma.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("person-row-" + p_cam).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_1).getByTestId("claim-due")).toHaveText("5.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_1).getByTestId("claim-status")).toHaveText("DRAFT");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_1).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-due")).toHaveText("7.50");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-status")).toHaveText("DRAFT");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_uma.getByTestId("rollup-claimed-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-overdue-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("rollup-overdue-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-settled-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-open-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("bulk-settle-batch")).toHaveText("");
  await expect(pg_uma.getByTestId("rollup-cut-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("header-people-count")).toHaveText("1");
  await expect(pg_uma.getByTestId("header-claims-DRAFT-count")).toHaveText("2");
  await expect(pg_uma.getByTestId("header-claims-OPEN-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("header-claims-PENDING-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("header-claims-SETTLED-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("header-claims-VOID-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("header-claims-REVIEW-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("header-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("header-overdue-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("my-due-total")).toHaveText("");
  await expect(pg_uma.getByTestId("my-overdue-total")).toHaveText("");
  await expect(pg_uma.getByTestId("my-crew-due-total")).toHaveText("");
  expect(await ui.generatePlans(pg_uma)).toBe(0);
  expect(await ui.periodAction(pg_uma, "P2", "close")).toBe(true);
  expect(await ui.claimAction(pg_uma, c_cam_1, "open")).toBe(true);
  expect(await ui.remind(pg_uma, c_cam_1)).toBe(true);
  expect(await ui.claimAction(pg_uma, c_cam_0, "open")).toBe(false);
  const pg_wes = await ui.userPage(browser, "wes", sheet);
  expect(await ui.claimAction(pg_wes, c_cam_1, "settle")).toBe(true);
  expect(await ui.editPerson(pg_wes, p_cam, {"grade": "A", "gradeFrom": "2026-02-25"})).toBe(true);
  await ui.refresh(pg_wes);
  await expect(pg_wes.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("0.00");

